const row = $input.first()?.json ?? {};
const chat = $('Entrada unificada').first().json;
const sessionId = String(chat.sessionId || 'sesion-manual');
const existe = Boolean(row.Session_ID);

return [{
  json: {
    Session_ID: sessionId,
    Usuario: row.Usuario || 'Usuario QA',
    Fecha_Actualizacion: row.Fecha_Actualizacion || '',
    Resumen_Consolidado: row.Resumen_Consolidado || '{"asunto_principal":"Sin contexto previo","puntos_clave":[],"accion_requerida":"ninguna"}',
    Estado_Caso: row.Estado_Caso || 'nuevo',
    Datos_Clave: row.Datos_Clave || '[]',
    Cantidad_Mensajes: Number(row.Cantidad_Mensajes || 0),
    Buffer_Reciente: row.Buffer_Reciente || '',
    es_nuevo: !existe,
    consulta_actual: String(chat.chatInput || '')
  }
}];

