const base = $('Preparar contexto de memoria').first().json;
const agent = $input.first().json;
const chat = $('Entrada unificada').first().json;
const consulta = String(chat.chatInput || '').slice(0, 600);
const respuesta = String(agent.output || agent.text || 'Sin respuesta').slice(0, 1400);
const cantidad = Number(base.Cantidad_Mensajes || 0) + 1;
const entrada = `Usuario: ${consulta}\nAgente: ${respuesta}`;
const buffer = [base.Buffer_Reciente, entrada].filter(Boolean).join('\n---\n').slice(-12000);

return [{
  json: {
    ...base,
    output: respuesta,
    Cantidad_Mensajes: cantidad,
    Buffer_Reciente: buffer,
    necesita_resumen: cantidad > 5
  }
}];

const d = $input.first().json;
return [{ json: {
  Session_ID: d.Session_ID,
  Fecha_Actualizacion: new Date().toISOString(),
  Usuario: d.Usuario || 'Usuario QA',
  Resumen_Consolidado: d.Resumen_Consolidado,
  Estado_Caso: d.Estado_Caso || 'en_seguimiento',
  Datos_Clave: d.Datos_Clave || '[]',
  Cantidad_Mensajes: d.Cantidad_Mensajes,
  Buffer_Reciente: d.Buffer_Reciente,
  output: d.output
} }];

const raw = String($input.first().json.output || '').trim();
const cleaned = raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = {
    asunto_principal: 'Seguimiento de consultas QA',
    puntos_clave: [cleaned.slice(0, 800)],
    accion_requerida: 'revisar resumen manualmente'
  };
}
const anterior = $('Actualizar contador y buffer').first().json;
const puntos = Array.isArray(parsed.puntos_clave) ? parsed.puntos_clave : [];
const accion = String(parsed.accion_requerida || 'ninguna');

return [{ json: {
  Session_ID: anterior.Session_ID,
  Fecha_Actualizacion: new Date().toISOString(),
  Usuario: anterior.Usuario || 'Usuario QA',
  Resumen_Consolidado: JSON.stringify({
    asunto_principal: String(parsed.asunto_principal || 'Seguimiento QA'),
    puntos_clave: puntos,
    accion_requerida: accion
  }),
  Estado_Caso: accion.toLowerCase() === 'ninguna' ? 'en_seguimiento' : 'requiere_accion',
  Datos_Clave: JSON.stringify(puntos),
  Cantidad_Mensajes: 0,
  Buffer_Reciente: '',
  output: anterior.output
} }];
